//! The live editor's tool catalogue, shared by Studio and the stdio relay so the relay can list tools while Studio is closed.
use serde_json::{Value, json};
fn tool(name: &str, description: &str, properties: Value, required: &[&str]) -> Value {
    json!({"name":name,"description":description,"inputSchema":{"type":"object","properties":properties,"required":required,"additionalProperties":false}})
}
/// Tool descriptors served by a live Studio session.
pub fn catalog() -> &'static Value {
    static CATALOG: std::sync::OnceLock<Value> = std::sync::OnceLock::new();
    CATALOG.get_or_init(build_catalog)
}
fn build_catalog() -> Value {
    let session = json!({"type":"string","format":"uuid"});
    let revision = json!({"type":"integer","minimum":0});
    let mut list = json!({"tools":[
        tool("track_surface","Track one rigid planar surface on the GPU in the open Studio, exactly like its Track surface window, and save the result as a reusable Planar track node (one undo step). Runs in the background with progress shown in the editor: the call returns started, then inspect reports job (tool, status running/done/failed, completed/total frames, and when done the node and message). surface is four [x,y] corners in 0..1 composition coordinates, in perimeter order, on the start (reference) frame; end may precede start. Optional region is a larger area of the same plane to analyze; area_follows=screen keeps it fixed in frame. occlusion is a node whose alpha marks foreground objects to ignore. motion constrains the surface (auto uses perspective only when needed). refine aligns every pixel after matching. back_to 0 also tracks backward to the first frame (Studio joins both directions at start). Connect the node to planar_warp nodes with apply.",json!({"session":session,"revision":revision,"source":{"type":"string","format":"uuid"},"surface":{"type":"array","minItems":4,"maxItems":4,"items":{"type":"array","minItems":2,"maxItems":2,"items":{"type":"number"}}},"region":{"type":"array","minItems":4,"maxItems":4,"items":{"type":"array","minItems":2,"maxItems":2,"items":{"type":"number"}}},"start":{"type":"integer","minimum":0},"end":{"type":"integer","minimum":0},"feature_radius":{"type":"integer","minimum":3,"maximum":16},"search_radius":{"type":"integer","minimum":1,"maximum":48},"tolerance":{"type":"number","minimum":0.1,"maximum":32},"reanchor":{"type":"boolean"},"area_follows":{"enum":["surface","screen"],"default":"surface"},"occlusion":{"type":"string","format":"uuid"},"motion":{"enum":["auto","perspective","affine","similarity","translation"],"default":"auto"},"refine":{"type":"boolean","default":true},"back_to":{"type":"integer","minimum":0,"maximum":0}}),&["session","revision","source","surface","start","end"]),
        tool("segment_subject","Cut out a person or object and track it through the shot with a local AI model in the open Studio, exactly like its Select subject window. points are clicks in 0..1 composition coordinates on frame; positive=true marks the subject, false excludes an area; several points over a person (head, body, legs) select them reliably. Tracks from frame to end (default: the last composition frame); back_to 0 also tracks backward to the first frame. model: edgetam (fastest), sam2.1-base-plus or sam2.1-large (most precise), installed in Tools > AI models. detail (default true) adds a zoomed pass for feet, hands and hair; matting (default: when ViTMatte is installed) refines hair and soft edges. Runs in the background with progress in the editor: the call returns started, then inspect reports job (status, completed/total, and when done the Subject cutout node). Adds a Subject matte Footage node and a Subject cutout (Refine matte) node in one undo step; mattes are written beside the saved project.",json!({"session":session,"revision":revision,"source":{"type":"string","format":"uuid"},"points":{"type":"array","minItems":1,"maxItems":32,"items":{"type":"object","additionalProperties":false,"properties":{"x":{"type":"number","minimum":0,"maximum":1},"y":{"type":"number","minimum":0,"maximum":1},"positive":{"type":"boolean"}},"required":["x","y","positive"]}},"frame":{"type":"integer","minimum":0},"end":{"type":"integer","minimum":0},"back_to":{"type":"integer","minimum":0,"maximum":0},"model":{"enum":["edgetam","sam2.1-base-plus","sam2.1-large"],"default":"edgetam"},"detail":{"type":"boolean","default":true},"matting":{"type":"boolean"}}),&["session","revision","source","points","frame"]),
        tool("new_project","Replace the open project with a new, empty composition and return its session. Refuses when the open project has unsaved changes unless discard_changes is true; save first in the editor to keep them. frame_rate is {ticks, rate}, for example {\"ticks\":30,\"rate\":1} for 30 fps.",json!({"width":{"type":"integer","minimum":2,"maximum":8192},"height":{"type":"integer","minimum":2,"maximum":8192},"frame_rate":{"type":"object","properties":{"ticks":{"type":"integer","minimum":1},"rate":{"type":"integer","minimum":1}},"required":["ticks","rate"],"additionalProperties":false},"frame_count":{"type":"integer","minimum":1,"maximum":1000000},"discard_changes":{"type":"boolean"}}),&["width","height"]),
        tool("open_project","Open a project file (absolute path) in place of the current one. Loading runs in the background: the call returns started, then inspect reports busy until done and a new session once open (status and error report failures). Refuses unsaved changes unless discard_changes is true.",json!({"path":{"type":"string"},"discard_changes":{"type":"boolean"}}),&["path"]),
        tool("new_from_media","Create a new composition matched to a media file (absolute path): its size, frame rate and duration, with the media imported as footage. Runs in the background like open_project; refuses unsaved changes unless discard_changes is true.",json!({"path":{"type":"string"},"discard_changes":{"type":"boolean"}}),&["path"]),
        tool("import_media","Import video, PNG, OpenEXR or (sequence true) a numbered image sequence from an absolute path into the open project as a new Footage node, exactly like Import media. An audio file is added as a Sound node on the timeline. An SVG drawing is added as vector shapes instead (per shape a Path outline to extrude with text_3d, a Solid of its colour and a Mask layer, merged back to front; the merged drawing is selected). Runs in the background: returns started; when done the imported node is selected (inspect.selected). match_composition makes an empty composition adopt the media's size, rate and duration; it is never asked interactively. Requires the current session and revision.",json!({"session":session,"revision":revision,"path":{"type":"string"},"sequence":{"type":"boolean"},"match_composition":{"type":"boolean"},"position":{"type":"object","properties":{"x":{"type":"number"},"y":{"type":"number"}},"required":["x","y"],"additionalProperties":false}}),&["session","revision","path"]),
        tool("inspect","Read project state and revision. Set summary=true for compact composition metadata without node payloads; graph and get_node provide targeted inspection.",json!({"summary":{"type":"boolean"}}),&[]),
        tool("graph","Page node metadata in stable UUID order without parameter payloads. Labels over 256 characters are marked as truncated. Compare revisions between pages.",json!({"offset":{"type":"integer","minimum":0},"limit":{"type":"integer","minimum":1,"maximum":128}}),&[]),
        tool("get_node","Read one exact authored node, or just a named parameter. Does not evaluate curves or change selection.",json!({"id":{"type":"string","format":"uuid"},"parameter":{"type":"string"}}),&["id"]),
        tool("diagnostics","Read GPU buffer and cache counters without waiting for an active render. Snapshot is null while the renderer is busy. Declared buffers exclude driver and rasterizer scratch allocations.",json!({}),&[]),
        tool("nodes","Read built-in operations, ports, defaults and parameter schemas.",json!({}),&[]),
        tool("materials","Every material that apply_material accepts: family surfaces (source family: changes the surface kind and keeps the target's finish and lighting), catalogue looks and saved materials (whole looks), with label, category, description and whether the user starred it. Saved ids are saved:<name>.",json!({}),&[]),
        tool("apply_material","Put a material from materials on a Text node (adding or restyling its Text surface, exactly like the library) or restyle a Text surface node in place. One undo step; output and wiring stay. Selects and previews the target.",json!({"session":session,"revision":revision,"target":{"type":"string","format":"uuid"},"material":{"type":"string","minLength":1,"maxLength":256},"dry_run":{"type":"boolean"}}),&["session","revision","target","material"]),
        tool("get_preset","Read a bundled starter, or capture a group with its current values and animation. Supply exactly one of starter or group. No filesystem access.",json!({"group":{"type":"string","format":"uuid"},"starter":{"type":"string","enum":veylvik_document::presets::builtin::ALL.map(|p|p.id).as_slice()}}),&[]),
        tool("insert_preset","Insert an independent instance with explicitly bound inputs. One undo step; output remains unchanged. Dry-run IDs are provisional.",json!({"session":session,"revision":revision,"preset":veylvik_document::schema::preset(),"inputs":{"type":"object","additionalProperties":{"type":"string","format":"uuid"}},"sizing":{"type":"string","enum":["fit","fill","original"],"default":"fit"},"position":veylvik_document::schema::position(),"dry_run":{"type":"boolean"}}),&["session","revision","preset","inputs"]),
        tool("apply","Validate or atomically apply commands to the open editor. Requires the session and revision from inspect. set_parameter and set_key preserve node identity and wiring. Image references must already be known to the editor; new paths require import. Unapplied inspector changes or file jobs block mutation.",json!({"session":session,"revision":revision,"dry_run":{"type":"boolean"},"commands":{"type":"array","minItems":1,"maxItems":4096,"items":veylvik_document::schema::command()}}),&["session","revision","commands"]),
        tool("add_effect","Create an editable effect group with exposed controls and ordinary internal nodes as one undoable transaction. Places the effect without overlapping existing nodes, selects/previews its root, and preserves composition output. Returns named role IDs for editing controls. Discover recipes with nodes; dry-run IDs are provisional.",json!({"session":session,"revision":revision,"input":{"type":"string","format":"uuid"},"recipe":{"type":"string","enum":veylvik_document::recipes::Recipe::ALL},"dry_run":{"type":"boolean"}}),&["session","revision","input","recipe"]),
        tool("duplicate_branch","Copy a node and all upstream dependencies as one undoable transaction, preserving shared ancestors and asset references. Places the copy outside existing graph bounds, selects/previews its root, and leaves composition output unchanged. Returns root and old-to-new ID mapping. Dry-run IDs are provisional and are not reused on commit.",json!({"session":session,"revision":revision,"node":{"type":"string","format":"uuid"},"dry_run":{"type":"boolean"}}),&["session","revision","node"]),
        tool("undo","Undo one editor transaction.",json!({"session":session,"revision":revision}),&["session","revision"]),
        tool("redo","Redo one editor transaction.",json!({"session":session,"revision":revision}),&["session","revision"]),
        tool("preview_image","Capture the current completed preview as an inline PNG without changing the editor. Use preview to pause/seek first; pending or stale frames are rejected. Captures applied pixels, excluding inspector drafts, overlays and viewer exposure/alpha settings. Encoding runs in the background; returned session/revision/time identify the captured snapshot.",json!({"session":session,"revision":revision,"max_edge":{"type":"integer","minimum":1,"maximum":2048}}),&["session","revision"]),
        tool("preview","Pause playback, seek to an absolute frame and optionally preview a node. The GPU preview is asynchronous; composition output is unchanged.",json!({"session":session,"revision":revision,"frame":{"type":"integer","minimum":0,"maximum":1000000},"node":{"type":"string","format":"uuid"}}),&["session","revision","frame"])
    ]});
    let region = || json!({"type":"string","format":"uuid"});
    list["tools"].as_array_mut().unwrap().extend([
        tool("measure","Read numbers back from a rendered frame instead of a picture: displayed brightness percentiles (0..1 after the display transform and the sRGB curve), scene-linear mean, peak and where it is, the share of pixels above 1.0, how much of the frame is covered and the box round everything that is not transparent (in composition pixels). Use it to check exposure, find where a node's picture lands in the frame, or compare two versions. Measures the completed preview: use preview to pause, seek and choose the node first, and wait until inspect.preview.rendering is false. region measures part of the frame.",json!({"session":session,"revision":revision,"region":{"type":"object","properties":{"x":{"type":"integer","minimum":0},"y":{"type":"integer","minimum":0},"width":{"type":"integer","minimum":1},"height":{"type":"integer","minimum":1}},"required":["x","y","width","height"],"additionalProperties":false}}),&["session","revision"]),
        tool("save","Save the open project. Without path it saves where the project already lives; with an absolute path it saves there and the project moves to it (like Save as). Runs in the background: returns started, then inspect.status reports Saved or the error.",json!({"session":session,"revision":revision,"path":{"type":"string"}}),&["session","revision"]),
        tool("render","Render one frame of the open project to a new .png (SDR) or .exr (linear) file at an absolute path, through the editor's render queue: returns started, and inspect.render_queue lists the job and its state. frame defaults to the frame shown; node to the composition's output. Existing files are refused.",json!({"session":session,"revision":revision,"path":{"type":"string"},"frame":{"type":"integer","minimum":0},"node":region()}),&["session","revision","path"]),
        tool("render_sequence","Render an inclusive frame range into a new directory (absolute path) as png or exr frames, through the editor's render queue: returns started, and inspect.render_queue lists the job and its progress.",json!({"session":session,"revision":revision,"path":{"type":"string"},"start":{"type":"integer","minimum":0},"end":{"type":"integer","minimum":0},"format":{"enum":["png","exr"]},"node":region()}),&["session","revision","path","start","end"]),
        tool("render_video","Export the open project's output to a new MP4 (absolute path) through the editor's render queue: returns started, and inspect.render_queue lists the job and its progress. Defaults to the composition's size, rate and range, H.264 high quality; settings names only what differs. settings.audio may set mute, music (an extra file from the first frame) and music_gain_db; settings.replace allows replacing an existing file.",json!({"session":session,"revision":revision,"path":{"type":"string"},"settings":{"type":"object","additionalProperties":false,"properties":{"width":{"type":"integer","minimum":2,"maximum":8192},"height":{"type":"integer","minimum":2,"maximum":8192},"frame_rate":{"type":"object","properties":{"ticks":{"type":"integer","minimum":1},"rate":{"type":"integer","minimum":1}},"required":["ticks","rate"],"additionalProperties":false},"start":{"type":"integer","minimum":0},"end":{"type":"integer","minimum":0},"codec":{"enum":["h264","hevc10"]},"quality":{"enum":["draft","high","master"]},"allow_software":{"type":"boolean"},"matte":{"type":"array","minItems":3,"maxItems":3,"items":{"type":"number","minimum":0,"maximum":1}},"replace":{"type":"boolean"},"audio":{"type":"object","additionalProperties":false,"properties":{"mute":{"type":"boolean"},"music":{"type":"string"},"music_gain_db":{"type":"number","minimum":-60,"maximum":12}}}}}}),&["session","revision","path"]),
        tool("outline_text","Read an explicit font file and convert text lines into Path geometry, without changing the project. Runs in the background: returns started, then inspect.job reports done with result.operation, to add with a put command or add_node.",json!({"session":session,"revision":revision,"font":{"type":"string"},"text":{"type":"string","maxLength":4096},"alignment":{"enum":["left","center","right"]},"line_height":{"type":"number","minimum":1,"maximum":4096},"font_index":{"type":"integer","minimum":0,"maximum":u32::MAX},"font_size":{"type":"number","minimum":1,"maximum":1024},"origin":{"type":"array","minItems":2,"maxItems":2,"items":{"type":"number","minimum":-32768,"maximum":32768}},"direction":{"enum":["left_to_right","right_to_left"]},"language":{"type":"string","minLength":1,"maxLength":64}}),&["session","revision","font","text"]),
        tool("solve_camera","Solve the real camera of a filmed shot in the open Studio, exactly like its Solve camera window, so 3D sits in the footage: adds a Solved camera, a ground when one is found, the solved scene, its render and the composite over the footage as one undo step. Runs in the background with progress in the editor: returns started, then inspect.job reports status, progress and, when done, the report with the new node ids. focal_length (mm) is found when left out.",json!({"session":session,"revision":revision,"source":{"type":"string","format":"uuid"},"start":{"type":"integer","minimum":0},"end":{"type":"integer","minimum":0},"focal_length":{"type":"number","minimum":1,"maximum":2000},"sensor_width":{"type":"number","minimum":1,"maximum":100}}),&["session","revision","source"]),
    ]);
    for (name, description, mut properties, required) in veylvik_presets::authoring::tools() {
        properties["session"] = session.clone();
        properties["revision"] = revision.clone();
        properties["dry_run"] = json!({"type":"boolean"});
        let required: Vec<&str> = required
            .iter()
            .copied()
            .chain(["session", "revision"])
            .collect();
        list["tools"]
            .as_array_mut()
            .unwrap()
            .push(tool(name, description, properties, &required));
    }
    list
}
